import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import makeAnimated from "react-select/animated"
import { useDispatch, useSelector } from "react-redux";
import { toast, ToastContainer } from "react-toastify";
import { useNavigate } from "react-router-dom";
import usersApi from "../../api/usersApi";
import { logOutUser } from "../../helpers/authUtils";
import Loading from "../../components/Loading";



export default function OTPModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();

    const moment = require("moment");
    const dispatch = useDispatch();
    const user = useSelector((state) => state.Auth.user);
    const success = useSelector((state) => state.Auth.success);
    const tokens = useSelector((state) => state.Auth.tokens);
    const errors = useSelector((state) => state.Auth.errors);
    const loading = useSelector((state) => state.Auth.loading);

    const navigate = useNavigate();



    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    // useEffect(() => {
    //     if (tokens) {
    //         navigate("/");
    //     }
    // }, [tokens]);

    const usersActionApi = useApi(usersApi.usersAction)

    const verifyOTP = async (data) => {
        const result = await usersActionApi.request(data)
        if (result.ok) {
            setopenEditModal(false)
            logOutUser()
            navigate("/")

        }

        console.log('result at validate otp', result)
    }

    const formik = useFormik({
        initialValues: {
            "otp": "",
        },

        validationSchema: Yup.object({
            otp: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("First name is required"),

        }),
        onSubmit: (values, { resetForm }) => {
            let phone = ""
            console.log('Valz', values)

            verifyOTP({
                "action": "VerifyOTP",
                "otp": values.otp


            })
        },
    });




    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);





    const resendOTP = async () => {
        const result = await usersActionApi.request({
            "action": "SendOTP"

        })

        console.log('result', result)
    }

    useEffect(() => {
        resendOTP()
    }, [])

    return (
        <>
            <Modal
                isOpen={openEditModal}
                placement="middle"
            >
                <ModalContent>
                    {(onClose) => (
                        loading ? <Loading loading={loading} /> : <form className="items-center grid grid-cols-1"
                            onSubmit={formik.handleSubmit}
                        >
                            <ModalHeader className="flex flex-col gap-1 items-center">Verify your phone number!</ModalHeader>
                            <ModalBody className="flex flex-col gap-1 items-center">Enter code received on your phone as sms</ModalBody>
                            <div className="m-5">
                                <ToastContainer position="bottom-center" theme="colored" />
                            </div>
                            <ModalBody>




                                <Input
                                    id="otp"
                                    name="otp"
                                    autoFocus
                                    label="One Time Pin"
                                    placeholder="Enter OTP"
                                    variant="bordered"
                                    type="text"
                                    onChange={formik.handleChange}
                                    onBlur={formik.handleBlur}
                                    defaultValue={formik.values.otp}
                                    value={formik.values.otp}
                                />

                                <div>     <Button onPress={() => resendOTP()} color="primary" href="#" size="sm">
                                    Resent OTP
                                </Button>
                                </div>

                            </ModalBody>
                            <ModalFooter className="items-center justify-center">
                                <Button color="danger" variant="flat" onPress={() => navigate("unauthorized")}>
                                    Close
                                </Button>
                                <Button type="submit" color="primary" onPress={onClose}>
                                    Sign in
                                </Button>
                            </ModalFooter>
                        </form>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
