import client from "./client";

const usersAdminAction = (data) => {
    return client.post("/authentication/users/admin", data);
};
const usersAction = (data) => {
    return client.post("/authentication/users", data);
};

const referenceNumbersAction = (data) => {
    return client.post("/authentication/users", data);
};

const referenceNumberAction = (data) => {
    return client.post("/authentication/users/reference", data);
};

const createCorporateUserAction = (data) => {
  return client.post("/authentication/register/corporate", data);
};

export default {
  usersAdminAction,
  usersAction,
  referenceNumbersAction,
  referenceNumberAction,
  createCorporateUserAction,
};
